"use strict";
// A seed packet: the variety and the note are its own members (the note
// holds undefined), the lot number is its own but not enumerable, and the
// shelf life comes from the class.
class Stock {
  get shelfLife() {
    return 3;
  }
}
function packet(variety) {
  const made = new Stock();
  made.variety = variety;
  made.note = undefined;
  Object.defineProperty(made, "lot", { value: 41, enumerable: false });
  return made;
}
exports.packet = packet;
exports.typedPacket = packet;
exports.relabel = (made) => {
  made.sowBy = "May";
  delete made.variety;
};
